<?php
namespace App\Controllers;use App\Core\{Authorization,CSRF,Database,TenantContext,View,Audit,HttpException};
final class PrivacyController{public function show(string $id):void{Authorization::require('privacy.manage');$t=TenantContext::id();$s=Database::connection()->prepare('SELECT * FROM customers WHERE id=:id AND tenant_id=:tenant');$s->execute(['id'=>(int)$id,'tenant'=>$t]);$customer=$s->fetch();if(!$customer)HttpException::abort(403,'Cliente não encontrado.');$c=Database::connection()->prepare('SELECT * FROM customer_consents WHERE tenant_id=:tenant AND customer_id=:id ORDER BY created_at DESC');$c->execute(['tenant'=>$t,'id'=>$id]);View::render('customers/privacy',['title'=>'Privacidade','customer'=>$customer,'consents'=>$c->fetchAll()]);}public function consent():void{Authorization::require('privacy.manage');CSRF::enforce();$t=TenantContext::id();$id=filter_var($_POST['customer_id']??null,FILTER_VALIDATE_INT);$type=(string)($_POST['type']??'');if(!$id||!in_array($type,['marketing_whatsapp','marketing_email','operational_reminders'],true)){http_response_code(422);exit('Dados inválidos.');}$check=Database::connection()->prepare('SELECT 1 FROM customers WHERE id=:id AND tenant_id=:tenant');$check->execute(['id'=>$id,'tenant'=>$t]);if(!$check->fetchColumn())HttpException::abort(403,'Cliente não encontrado.');Database::connection()->prepare("INSERT INTO customer_consents(tenant_id,customer_id,type,granted,version,source,ip_address,created_at)VALUES(:tenant,:customer,:type,:granted,'1.0','admin',:ip,NOW())")->execute(['tenant'=>$t,'customer'=>$id,'type'=>$type,'granted'=>isset($_POST['granted'])?1:0,'ip'=>$_SERVER['REMOTE_ADDR']??null]);Audit::log('privacy.consent','customers',(int)$id);header('Location: /customers/'.$id.'/privacy');exit;}public function export(string $id):void{Authorization::require('privacy.manage');$t=TenantContext::id();$pdo=Database::connection();$s=$pdo->prepare('SELECT id,name,phone,email,birth_date,created_at FROM customers WHERE id=:id AND tenant_id=:tenant');$s->execute(['id'=>(int)$id,'tenant'=>$t]);$customer=$s->fetch();if(!$customer)HttpException::abort(403,'Cliente não encontrado.');$a=$pdo->prepare('SELECT service_id,starts_at,ends_at,status,source FROM appointments WHERE tenant_id=:tenant AND customer_id=:id');$a->execute(['tenant'=>$t,'id'=>$id]);$payload=['exported_at'=>date(DATE_ATOM),'customer'=>$customer,'appointments'=>$a->fetchAll()];Audit::log('privacy.export','customers',(int)$id);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="customer-'.$id.'-export.json"');header('Cache-Control: no-store, private');echo json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);}}
